import 'package:sqflite/sqflite.dart';
import 'package:sqflite_common_ffi_web/sqflite_ffi_web.dart';

import '../../data/storage/data_uri_image_storage_service.dart';
import '../../data/storage/image_storage_service.dart';
import '../../features/camera_scan/services/ocr_service.dart';
import '../../features/camera_scan/services/tesseract_ocr_service.dart';

/// Web has no native SQLite; use the WASM build (needs web/sqlite3.wasm,
/// generated by `dart run sqflite_common_ffi_web:setup`). Runs on the main
/// thread, without the shared worker: simpler and works in every browser,
/// including iOS Safari PWAs. Data persists in IndexedDB.
Future<void> initPlatform() async {
  databaseFactory = databaseFactoryFfiWebNoWebWorker;
}

OcrService createOcrService() => TesseractOcrService();

ImageStorageService createImageStorage() => DataUriImageStorageService();
